def choose_move(observation):
    # Basic deterministic approach: move toward closest resource, else toward center, else stay.
    width = observation.get("grid_width", 0)
    height = observation.get("grid_height", 0)
    pos = observation.get("self_position", (0, 0))
    ox, oy = pos
    resources = observation.get("resources", [])
    # fallback if resources absent
    best_r = None
    best_d = 10**9
    for r in resources:
        rx = r.get("x", 0)
        ry = r.get("y", 0)
        d = abs(ox - rx) + abs(oy - ry)
        if d < best_d:
            best_d = d
            best_r = (rx, ry)
    dx = 0
    dy = 0
    if best_r is not None:
        rx, ry = best_r
        if ox < rx:
            dx = 1
        elif ox > rx:
            dx = -1
        else:
            dx = 0
        if oy < ry:
            dy = 1
        elif oy > ry:
            dy = -1
        else:
            dy = 0
        return [dx, dy]
    # If no resources, move toward center of grid if known
    if width and height:
        cx = width // 2
        cy = height // 2
        if ox < cx:
            dx = 1
        elif ox > cx:
            dx = -1
        else:
            dx = 0
        if oy < cy:
            dy = 1
        elif oy > cy:
            dy = -1
        else:
            dy = 0
        return [dx, dy]
    # Default stay
    return [0, 0]
